stripCaptureSuffix(name) {
	this.eventName = name;
	this.eventTarget = this.eventTarget;
	let next = name.replace(/(PointerCapture)$|Capture$/i, '$1');
	let useCapture = name !== next;
	this.eventName = next;
	this.eventCaptureMode = useCapture;
